#!name=51信用卡管家
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = api.u51.com

[Rewrite]
request if ${url} ~= /^https?:\/\/api\.u51\.com\/(generic-config-gateway|rs-resys)\/api\/v\d\/(creditpage-config|recommend)/i then reject(200)

[Script]
response if ${url} ~= /^https?:\/\/api\.u51\.com\/liabilitygateway\/api\/v\d\/homepage\/liabilityline/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/51card.js") with enable=${51xyk_enable}, tag="51信用卡管家", timeout=60, requires_body=true
response if ${url} ~= /^https?:\/\/api\.u51\.com\/generic-config-gateway\/api\/v\d\/guanjia\/me-tab2\/config/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/51card.js") with enable=${51xyk_enable}, tag="51信用卡管家", timeout=60, requires_body=true
